css:
.ss-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.ss-post{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line)}
.ss-post[hidden]{display:none}
.ss-post__m{display:block;height:190px;background:var(--paper);overflow:hidden}
.ss-post__m img{width:100%;height:100%;object-fit:cover;display:block}
.ss-post__b{display:flex;flex-direction:column;flex:1;padding:24px 22px 26px}
.ss-post__meta{display:flex;align-items:baseline;flex-wrap:wrap;gap:10px;margin-bottom:12px}
.ss-post__topic{font:700 10px/1.3 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.ss-post__date{font:400 12px/1.3 var(--font-body);color:var(--muted)}
.ss-post__t{font:700 19px/1.3 var(--font-heading);letter-spacing:normal;margin:0 0 12px}
.ss-post__t a{color:var(--ink);text-decoration:none}
.ss-post__t a:hover{color:var(--accent)}
.ss-post__x{font:400 14px/1.7 var(--font-body);color:var(--body-text);margin:0 0 18px}
.ss-post__more{margin-top:auto;font:700 14px/1.6 var(--font-body);color:var(--accent);text-decoration:none}
.ss-post__more:hover{text-decoration:underline;text-underline-offset:3px}
.ss-posts__empty{margin:24px 0 0;border-top:1px solid var(--line);padding-top:22px;font:400 15px/1.7 var(--font-body);color:var(--muted)}
.ss-posts__empty[hidden]{display:none}
@media (max-width:1100px){.ss-posts{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.ss-posts{grid-template-columns:minmax(0,1fr)}}
